class Solution {
  public int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
      ones = ones ^ (num & ~twos);
      twos = twos ^ (num & ~ones);
    }
    return ones;
  }
}

class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        ones, twos = 0, 0
        for num in nums:
            ones = ones ^ (num & ~twos)
            twos = twos ^ (num & ~ones)
        return ones

impl Solution {
  pub fn single_number(nums: Vec<i32>) -> i32 {
    let (mut ones, mut twos) = (0, 0);
    for num in nums {
      ones = ones ^ (num & !twos);
      twos = twos ^ (num & !ones);
    }
    ones
  }
}

const singleNumber = (nums: number[]): number => {
  let ones = 0;
  let twos = 0;
  for (const num of nums) {
    ones = ones ^ (num & ~twos);
    twos = twos ^ (num & ~ones);
  }
  return ones;
};

int singleNumber(int *nums, int numsSize) {
  int ones = 0, twos = 0;
  for (int i = 0; i < numsSize; i++) {
    ones = ones ^ nums[i] & ~twos;
    twos = twos ^ nums[i] & ~ones;
  }
  return ones;
}

